using System;
using System.Collections.Generic;
using System.Linq;

namespace Prometheus {
 public sealed class ManualMaskKeyframe {public double source_seconds;public ClipMask mask;}
 public sealed class ManualMaskTrack {public bool enabled=true;public string interpolation="linear",target="opacity";public List<ManualMaskKeyframe> points=new List<ManualMaskKeyframe>();}
 public static class TemporalMasks0823 {
  public const string Namespace="prometheus.mask.manual.v1";
  public static ManualMaskTrack Get(Clip clip){var item=clip.extensions==null?null:clip.extensions.FirstOrDefault(x=>x.@namespace==Namespace);return item==null?null:Store.Json().Deserialize<ManualMaskTrack>(Store.Json().Serialize(item.payload));}
  static ClipMask Copy(ClipMask mask){if(mask==null)return null;return new ClipMask{shape=mask.shape,enabled=mask.enabled,inverted=mask.inverted,feather=mask.feather,points=mask.points.Select(p=>new MaskVertex{x=p.x,y=p.y}).ToList()};}
  public static void Put(Clip clip,ManualMaskTrack track){if(clip.extensions==null)clip.extensions=new List<Extension>();clip.extensions.RemoveAll(x=>x.@namespace==Namespace);if(track!=null)clip.extensions.Add(new Extension{@namespace=Namespace,version="1",payload=(Dictionary<string,object>)Store.Fields(track)});}
  public static void Set(Clip clip,double timelineSeconds,ClipMask mask){ClipMasks.Validate(mask);var track=Get(clip)??new ManualMaskTrack();double source=Math.Round(ClipKeyframes.SourceAt(clip,timelineSeconds)*48000)/48000.0;track.points.RemoveAll(p=>Math.Abs(p.source_seconds-source)<1.0/48000);track.points.Add(new ManualMaskKeyframe{source_seconds=source,mask=Copy(mask)});track.points=track.points.OrderBy(p=>p.source_seconds).ToList();Put(clip,track);clip.mask=Copy(mask);}
  public static ClipMask At(Clip clip,double timelineSeconds){var track=Get(clip);if(track==null||!track.enabled||track.points.Count==0)return clip.mask;double source=ClipKeyframes.SourceAt(clip,timelineSeconds);var points=track.points.OrderBy(p=>p.source_seconds).ToList();if(source<=points[0].source_seconds)return Copy(points[0].mask);for(int i=1;i<points.Count;i++)if(source<=points[i].source_seconds){var a=points[i-1];var b=points[i];double u=(source-a.source_seconds)/(b.source_seconds-a.source_seconds);if(track.interpolation=="hold")u=0;else if(track.interpolation=="bezier")u=u*u*(3-2*u);return Mix(a.mask,b.mask,u);}return Copy(points[points.Count-1].mask);}
  static ClipMask Mix(ClipMask a,ClipMask b,double u){if(a.shape!=b.shape||a.points.Count!=b.points.Count)return Copy(u<0.5?a:b);var result=Copy(a);for(int i=0;i<result.points.Count;i++){result.points[i].x=a.points[i].x+(b.points[i].x-a.points[i].x)*u;result.points[i].y=a.points[i].y+(b.points[i].y-a.points[i].y)*u;}result.feather=a.feather+(b.feather-a.feather)*u;result.inverted=u<0.5?a.inverted:b.inverted;return result;}
  public static bool HasAnimation(Clip clip){var track=Get(clip);return track!=null&&track.enabled&&track.points.Count>0;}
  public static string Target(Clip clip){var sam2=Sam2MaskStore090.Get(clip);if(sam2!=null&&sam2.enabled)return sam2.target??"opacity";var manual=Get(clip);return manual==null?"opacity":manual.target??"opacity";}
  public static void SetTarget(Clip clip,string target,bool sam2){if(String.IsNullOrWhiteSpace(target)||target!="opacity"&&target!="unassigned"&&!target.StartsWith("effect:",StringComparison.Ordinal))throw new Exception("Destino de máscara inválido");if(sam2){var track=Sam2MaskStore090.Get(clip);if(track==null)throw new Exception("No hay máscara SAM2");track.target=target;Sam2MaskStore090.Put(clip,track);}else{var track=Get(clip)??new ManualMaskTrack();track.target=target;Put(clip,track);}}
  public static void Validate(Clip clip){var track=Get(clip);if(track==null)return;if(!(new[]{"linear","bezier","hold"}).Contains(track.interpolation)||track.points==null||track.points.Count>20000||String.IsNullOrWhiteSpace(track.target)||track.target!="opacity"&&track.target!="unassigned"&&!track.target.StartsWith("effect:",StringComparison.Ordinal))throw new Exception("Animación de máscara inválida");double previous=-1;foreach(var point in track.points){if(point==null||Double.IsNaN(point.source_seconds)||point.source_seconds<0||point.source_seconds<=previous)throw new Exception("Tiempo de máscara inválido");ClipMasks.Validate(point.mask);previous=point.source_seconds;}}
 }
}
